DUT.Declaration:
TYPE ST_EpsonRobotAdsData :
STRUCT
    bAutoMode             : BOOL := TRUE;
    bSafetyPermissive     : BOOL := TRUE;
    stTransfer            : ST_EpsonTransferState :=
                                (
                                Ready               := TRUE,
                                WaferExpected       := TRUE
                                );

    stPress               : ST_EpsonPressState :=
                                (
                                Ready               := TRUE,
                                PlatePresent        := TRUE,
                                ThinPlate           := FALSE,
                                TargetSlotFree      := TRUE
                                );

    stToolStat            : ST_EpsonToolStationState :=
                                (
                                Ready               := TRUE,
                                DoorLocked          := TRUE
                                );

    stGenmark             : ST_EpsonRobotState :=
                                (
                                Ready               := TRUE,
                                Idle                := TRUE,
                                Parked              := TRUE
                                );

    stStaeubli            : ST_EpsonRobotState :=
                                (
                                Ready               := TRUE,
                                Idle                := TRUE,
                                Parked              := TRUE
                                );

    // Locks
    bTransferAllowed        : BOOL := TRUE;
    bPressAllowed           : BOOL := TRUE;
    bToolStatAllowed        : BOOL := TRUE;
    bGenmarkAllowed         : BOOL := TRUE;
    bStaeubliAllowed        : BOOL := TRUE;
END_STRUCT
END_TYPE
